export type EntryFollowUpKey = keyof typeof ENTRY_FOLLOW_UP_MESSAGES;

// ---------------------------------------------------------------------------
// Fixing (GetExchangeRateCommand, 02a 2)

export interface FixingLineInput {
  amount: DecInput | null;
  currencyAmount: DecInput | null;
}

/**
 * A foreign-currency line after the fixing of the date was applied as its
 * rate: Amount = round2(CurrencyAmount * Rate) when a currency amount is
 * entered, otherwise CurrencyAmount = round2(Amount / Rate) (02a 2).
 */
export function lineWithFixing(l: FixingLineInput, rate: DecInput): { exchangeRate: Dec; fixedRate: Dec; amount: Dec | null; currencyAmount: Dec | null } {
  const r = dec(rate);
  const ca = l.currencyAmount != null && l.currencyAmount !== '' ? dec(l.currencyAmount) : null;
  const a = l.amount != null && l.amount !== '' ? dec(l.amount) : null;
  if (ca && !ca.isZero()) return { exchangeRate: r, fixedRate: r, amount: amountFromCurrency(ca, r), currencyAmount: ca };
  if (a && !a.isZero()) return { exchangeRate: r, fixedRate: r, amount: round2(a), currencyAmount: currencyFromAmount(a, r) };
  return { exchangeRate: r, fixedRate: r, amount: a, currencyAmount: ca };
}

// ---------------------------------------------------------------------------
// After save (02a 4.4, 03b 14.1)

export interface AssetOfferLine {
  accountId: number;
  accountNumber: string;
  amount: DecInput;
  isCompany?: boolean;
}

/**
 * strAddFixedAssetData (03b 14.1): a new posting whose debit line is on a
 * fixed-asset account (number starting with "2") and whose credit side has
 * no partner account offers a new asset; returns that debit line or null.
 */
export function fixedAssetOffer(debits: AssetOfferLine[], credits: AssetOfferLine[]): AssetOfferLine | null {
  if (credits.some((l) => l.isCompany)) return null;
  return debits.find((l) => l.accountNumber.startsWith('2') && !dec(l.amount).isZero()) ?? null;
}

/** 03b 6.1 "created from a posting": the asset form's prefill. */
export function assetFromPosting(p: { accountId: number; accountDescription: string; amount: DecInput; date: string; term?: string | null }) {
  const amount = round2(p.amount).abs();
  return {
    inventoryAccountId: p.accountId,
    name: (p.term?.trim() || p.accountDescription).slice(0, 255),
    acquisitionDate: p.date,
    startDate: p.date,
    depreciationAmount: amount.toFixed(2),
  };
}

// ---------------------------------------------------------------------------
// Postings of the asset module (03b 12.3, 02a 5.1)

/** Entry sources of the asset module whose edit or void is warned about. */
export function linkedPostingWarning(source: string | null | undefined): { key: EntryFollowUpKey; text: string } | null {
  if (source === 'depreciation') return { key: 'strDepreciationScheduleAttachedWarning', text: ENTRY_FOLLOW_UP_MESSAGES.strDepreciationScheduleAttachedWarning };
  if (source === 'asset-writeoff') return { key: 'strVoidAccountingWithFixedAsset', text: ENTRY_FOLLOW_UP_MESSAGES.strVoidAccountingWithFixedAsset };
  return null;
}

// ---------------------------------------------------------------------------
// Partner account links (03a 2.9)

export interface PartnerLine {
  accountId: number;
  accountNumber: string;
  companyId: number | null;
  isCompany: boolean;
}

/**
 * Partner lines whose account the partner is not linked to (CompanyAccounts),
 * one per (partner, account); `linked` holds "companyId:accountId" keys.
 */
export function missingPartnerAccounts(lines: PartnerLine[], linked: ReadonlySet<string>): { companyId: number; accountId: number; accountNumber: string }[] {
  const out = new Map<string, { companyId: number; accountId: number; accountNumber: string }>();
  for (const l of lines) {
    if (!l.isCompany || !l.companyId) continue;
    const k = `${l.companyId}:${l.accountId}`;
    if (!linked.has(k) && !out.has(k)) out.set(k, { companyId: l.companyId, accountId: l.accountId, accountNumber: l.accountNumber });
  }
  return [...out.values()];
}

// ---------------------------------------------------------------------------
// Entry card (AccountingReport, 05 7.11)

export interface EntryCardLine {
  accountNumber: string;
  accountDescription: string;
  companyName?: string | null;
  amount: DecInput;
  currencyIso?: string | null;
  currencyAmount?: DecInput | null;
  exchangeRate?: DecInput | null;
  fixedRate?: DecInput | null;
  quantity?: DecInput | null;
  price?: DecInput | null;
  measure?: string | null;
}

export interface EntryCardSide {
  lines: EntryCardLine[];
  total: Dec;
  /** Currency columns (currency amount, rate, fixing) are printed. */
  hasCurrency: boolean;
  /** Material columns (quantity, price, measure) are printed. */
  hasMaterial: boolean;
}

const present = (v: DecInput | null | undefined) => v != null && v !== '';

/** Debit and credit tables of the entry card with their totals and optional columns. */
export function entryCardSides(debits: EntryCardLine[], credits: EntryCardLine[]): { debit: EntryCardSide; credit: EntryCardSide; balanced: boolean } {
  const side = (lines: EntryCardLine[]): EntryCardSide => ({
    lines,
    total: lines.length ? sum(lines.map((l) => dec(l.amount))) : ZERO,
    hasCurrency: lines.some((l) => present(l.currencyAmount) && !!l.currencyIso),
    hasMaterial: lines.some((l) => present(l.quantity)),
  });
  const debit = side(debits);
  const credit = side(credits);
  return { debit, credit, balanced: debit.total.eq(credit.total) };
}
